/* global d3 */

const chartWidth = 720;
const chartHeight = 620;
const clusterRadius = Math.min(chartWidth, chartHeight) * 0.22;
const tickCount = 280;
const etfRadius = 12;
const padding = 2;

const svg = d3.select('#bubble-chart')
  .append('svg')
  .attr('viewBox', `0 0 ${chartWidth} ${chartHeight}`)
  .attr('width', chartWidth)
  .attr('height', chartHeight);

const tooltip = d3.select('#tooltip');
let selectedTicker = null;
let rowSelection = null;
let nodeSelection = null;

const formatMarketCap = (value) => {
  if (value === null || value === undefined || !Number.isFinite(value)) {
    return '-';
  }
  const abs = Math.abs(value);
  if (abs >= 1e12) return `${(value / 1e12).toFixed(2)}T`;
  if (abs >= 1e9) return `${(value / 1e9).toFixed(2)}B`;
  if (abs >= 1e6) return `${(value / 1e6).toFixed(2)}M`;
  if (abs >= 1e3) return `${(value / 1e3).toFixed(2)}K`;
  return value.toFixed(2);
};

const clamp = (value, min, max) => Math.max(min, Math.min(max, value));

const setSelection = (ticker) => {
  selectedTicker = ticker;
  if (nodeSelection) {
    nodeSelection.classed('selected', d => d.ticker === selectedTicker);
  }
  if (rowSelection) {
    rowSelection.classed('selected', d => d.ticker === selectedTicker);
  }
};

d3.csv('data/stock-descriptions.csv').then(raw => {
  const data = raw.map((d, i) => {
    const mc = Number(d.marketCap);
    const marketCap = Number.isFinite(mc) ? mc : null;
    return {
      index: i,
      ticker: d.ticker,
      name: d['full name'],
      sector: d.sector,
      marketCap,
      isEtf: d.sector === 'ETF' || !Number.isFinite(mc)
    };
  });

  data.sort((a, b) => d3.ascending(a.ticker, b.ticker));

  const sectors = Array.from(new Set(data.map(d => d.sector))).sort(d3.ascending);
  const colorScale = d3.scaleOrdinal()
    .domain(sectors)
    .range(d3.schemeTableau10);

  const maxCap = d3.max(data, d => d.marketCap || 0);
  const radiusScale = d3.scaleSqrt()
    .domain([0, maxCap])
    .range([8, 46]);

  const sectorPositions = new Map();
  sectors.forEach((sector, i) => {
    const angle = (i / sectors.length) * Math.PI * 2;
    sectorPositions.set(sector, {
      x: chartWidth / 2 + Math.cos(angle) * clusterRadius,
      y: chartHeight / 2 + Math.sin(angle) * clusterRadius
    });
  });

  const buckets = new Map(sectors.map(sector => [sector, []]));
  data.forEach(d => buckets.get(d.sector).push(d));

  buckets.forEach((bucket, sector) => {
    bucket.sort((a, b) => d3.ascending(a.ticker, b.ticker));
    const cols = Math.ceil(Math.sqrt(bucket.length));
    const rows = Math.ceil(bucket.length / cols);
    const spacing = 16;
    const origin = sectorPositions.get(sector);
    bucket.forEach((d, i) => {
      const col = i % cols;
      const row = Math.floor(i / cols);
      const offsetX = (col - (cols - 1) / 2) * spacing;
      const offsetY = (row - (rows - 1) / 2) * spacing;
      d.x = origin.x + offsetX;
      d.y = origin.y + offsetY;
      d.radius = d.marketCap ? radiusScale(d.marketCap) : etfRadius;
    });
  });

  const simulation = d3.forceSimulation(data)
    .force('x', d3.forceX(d => sectorPositions.get(d.sector).x).strength(0.55))
    .force('y', d3.forceY(d => sectorPositions.get(d.sector).y).strength(0.55))
    .force('collide', d3.forceCollide(d => d.radius + padding))
    .force('charge', d3.forceManyBody().strength(-12))
    .force('center', d3.forceCenter(chartWidth / 2, chartHeight / 2))
    .stop();

  for (let i = 0; i < tickCount; i += 1) {
    simulation.tick();
  }

  data.forEach(d => {
    d.x = clamp(d.x, d.radius + padding, chartWidth - d.radius - padding);
    d.y = clamp(d.y, d.radius + padding, chartHeight - d.radius - padding);
  });

  const nodeGroup = svg.append('g').attr('class', 'nodes');

  nodeSelection = nodeGroup.selectAll('g')
    .data(data, d => d.ticker)
    .join('g')
    .attr('class', 'node')
    .attr('transform', d => `translate(${d.x}, ${d.y})`)
    .on('click', (event, d) => {
      setSelection(d.ticker);
    })
    .on('mouseover', (event, d) => {
      if (d.isEtf) {
        return;
      }
      tooltip
        .classed('visible', true)
        .html(`<strong>${d.ticker}</strong><br/>${d.name}<br/>Sector: ${d.sector}`);
    })
    .on('mousemove', (event, d) => {
      if (d.isEtf) {
        return;
      }
      tooltip
        .style('left', `${event.pageX + 12}px`)
        .style('top', `${event.pageY - 18}px`);
    })
    .on('mouseout', () => {
      tooltip.classed('visible', false);
    });

  nodeSelection.append('circle')
    .attr('r', d => d.radius)
    .attr('fill', d => colorScale(d.sector));

  nodeSelection.append('text')
    .attr('class', 'bubble-label')
    .style('font-size', d => `${Math.max(9, Math.min(14, d.radius * 0.55))}px`)
    .text(d => d.ticker);

  const legend = d3.select('#legend');
  const legendItems = legend.selectAll('.legend-item')
    .data(sectors)
    .join('div')
    .attr('class', 'legend-item');

  legendItems.append('span')
    .attr('class', 'legend-swatch')
    .style('background-color', d => colorScale(d));

  legendItems.append('span')
    .text(d => d);

  const tableColumns = [
    { key: 'ticker', label: 'Ticker symbol', format: d => d },
    { key: 'name', label: 'Full company name', format: d => d },
    { key: 'sector', label: 'Sector', format: d => d },
    { key: 'marketCap', label: 'Market cap', format: formatMarketCap }
  ];

  const table = d3.select('#table-container')
    .append('table')
    .attr('id', 'data-table');

  const thead = table.append('thead');
  const headerRow = thead.append('tr');
  headerRow.selectAll('th')
    .data(tableColumns)
    .join('th')
    .text(d => d.label);

  const tbody = table.append('tbody');
  rowSelection = tbody.selectAll('tr')
    .data(data, d => d.ticker)
    .join('tr')
    .on('click', (event, d) => {
      setSelection(d.ticker);
    });

  rowSelection.selectAll('td')
    .data(d => tableColumns.map(col => ({ value: d[col.key], format: col.format })))
    .join('td')
    .text(d => d.format(d.value));

  setSelection(data[0]?.ticker || null);
}).catch(err => {
  console.error('Failed to load data', err);
});
